def skjkasdkd(lst):
    def isPrime(n):
        """Check if a number is prime."""
        if n <= 1:
            return False
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                return False
        return True

    max_prime = 0
    for num in lst:
        if isPrime(num) and num > max_prime:
            max_prime = num

    return sum(int(digit) for digit in str(max_prime))

