def exchange(lst1, lst2):
    odd = 0
    even = 0

    # Counting odd and even elements in lst1
    for num in lst1:
        if num % 2 == 0:
            even += 1
        else:
            odd += 1

    # Counting odd and even elements in lst2
    for num in lst2:
        if num % 2 == 0:
            even += 1
        else:
            odd += 1

    # Checking the condition and returning the result
